package com.nequard.maintenance;
import com.nequard.auth.OrganizationAccessService;import com.nequard.network.Device;import com.nequard.network.DeviceRepository;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/work-orders") public class WorkOrderController{private final WorkOrderRepository repo;private final DeviceRepository devices;private final OrganizationAccessService access;public WorkOrderController(WorkOrderRepository r,DeviceRepository d,OrganizationAccessService a){repo=r;devices=d;access=a;}private void check(Authentication a,UUID deviceId){if(deviceId==null)throw new IllegalArgumentException("DEVICE_ID_REQUIRED");Device d=devices.findById(deviceId).orElseThrow(()->new NoSuchElementException("DEVICE_NOT_FOUND"));if(!access.canAccess(a,d.getOrganizationId()))throw new SecurityException("TENANT_ACCESS_DENIED");}@GetMapping public List<WorkOrder> all(Authentication a){if(access.isSuperAdmin(a))return repo.findAll();return repo.findAll().stream().filter(w->{try{check(a,w.getDeviceId());return true;}catch(RuntimeException e){return false;}}).toList();}@PostMapping public WorkOrder create(Authentication a,@RequestBody WorkOrder w){check(a,w.getDeviceId());return repo.save(w);}@PatchMapping("/{id}/status")public WorkOrder status(Authentication a,@PathVariable UUID id,@RequestParam String value){WorkOrder w=repo.findById(id).orElseThrow();check(a,w.getDeviceId());w.setStatus(value.toUpperCase());return repo.save(w);}}